  actor                        varchar(64),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE file_transfer_log IS 'Immutable audit of every action on a file or channel';
COMMENT ON COLUMN file_transfer_log.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN file_transfer_log.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN file_transfer_log.created_at IS 'Creation time';
COMMENT ON COLUMN file_transfer_log.created_by IS 'Principal that created the row';
COMMENT ON COLUMN file_transfer_log.file_channel_id IS 'Channel';
COMMENT ON COLUMN file_transfer_log.inbound_file_id IS 'Inbound file';
COMMENT ON COLUMN file_transfer_log.outbound_file_id IS 'Outbound file';
COMMENT ON COLUMN file_transfer_log.action IS 'Action';
COMMENT ON COLUMN file_transfer_log.success IS 'Outcome';
COMMENT ON COLUMN file_transfer_log.remote_address IS 'Remote IP / host';
COMMENT ON COLUMN file_transfer_log.bytes_transferred IS 'Bytes';
COMMENT ON COLUMN file_transfer_log.duration_ms IS 'Duration';
COMMENT ON COLUMN file_transfer_log.message IS 'Detail';
COMMENT ON COLUMN file_transfer_log.actor IS 'System or user';
COMMENT ON COLUMN file_transfer_log.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN file_transfer_log.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN file_transfer_log.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN file_transfer_log.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN file_transfer_log.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_file_transfer_log_tenant ON file_transfer_log (tenant_id, created_at);
CREATE INDEX ix_file_transfer_log_file_channel_id ON file_transfer_log (file_channel_id);
CREATE INDEX ix_file_transfer_log_inbound_file_id ON file_transfer_log (inbound_file_id);
CREATE INDEX ix_file_transfer_log_outbound_file_id ON file_transfer_log (outbound_file_id);
ALTER TABLE file_transfer_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON file_transfer_log USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_file_transfer_log_append_only BEFORE UPDATE OR DELETE ON file_transfer_log FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA file_gateway TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA file_gateway TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA file_gateway GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
